descriptor.templateCss:
.dcr {
    display: flex;
    flex-direction: column;
    width: 100%;
    height: 100%;
    box-sizing: border-box;
    padding: 8px 12px;
    overflow: hidden;
}

.dcr_clickable {
    cursor: pointer;
}

.dcr__head {
    flex: 0 0 auto;
}

.dcr__content {
    flex: 1 1 auto;
    display: flex;
    flex-direction: column;
    align-items: center;
    gap: 8px;

    min-height: 0;
    min-width: 0;
}

.dcr_row .dcr__content {
    flex-direction: row;
    align-items: stretch;
    justify-content: center;
    gap: 16px;
}

.dcr__ring {
    position: relative;
    flex: 1 1 auto;
    min-height: 0;
    min-width: 0;
    width: 100%;
}

.dcr_row .dcr__ring {
    flex: 0 0 auto;
    width: auto;
    height: 100%;
    aspect-ratio: 1 / 1;
}

.dcr_empty .dcr__ring,
.dcr_row.dcr_empty .dcr__ring {
    flex: 1 1 auto;
    width: 100%;
    height: 100%;
    aspect-ratio: auto;
}

.dcr__chart {
    position: absolute;
    inset: 0;
    overflow: hidden;
}

.dcr__center {
    position: absolute;
    inset: 0;
    display: flex;
    flex-direction: column;
    align-items: center;
    justify-content: center;
    gap: 2px;

    pointer-events: none;
    text-align: center;

    padding: 0 10%;
    box-sizing: border-box;
    overflow: hidden;
}

.dcr__center-value {
    white-space: nowrap;
    letter-spacing: -0.5px;
}

.dcr__center-label {
    max-width: 100%;
    overflow: hidden;
    text-overflow: ellipsis;
    white-space: nowrap;
}

.dcr__no-data {
    position: absolute;
    inset: 0;
    display: flex;
    align-items: center;
    justify-content: center;
    padding: 0 12px;
    box-sizing: border-box;
    text-align: center;
    font-size: 13px;
    line-height: 1.4;
    color: rgba(0, 0, 0, 0.45);
    white-space: normal;
    overflow-wrap: break-word;
}

.dcr__legend {
    flex: 0 1 auto;
    display: flex;
    flex-direction: column;
    justify-content: center;
    gap: 4px;
    min-width: 0;
    min-height: 0;

    max-height: 55%;
    overflow: auto;
}

.dcr_row .dcr__legend {
    flex: 1 1 auto;
    max-height: 100%;
}

.dcr__row {
    display: flex;
    align-items: baseline;
    gap: 8px;
    min-width: 0;
    white-space: nowrap;
}

.dcr__dot {
    flex: 0 0 auto;
    width: 8px;
    height: 8px;
    border-radius: 50%;
    align-self: center;
}

.dcr__label {
    flex: 0 1 auto;
    min-width: 0;
    overflow: hidden;
    text-overflow: ellipsis;
}

.dcr__now {
    flex: 0 0 auto;
    padding: 1px 6px;
    border-radius: 8px;
    font-size: 0.75em;
    line-height: 1.5;
    background: var(--tb-primary-50, #e8eaf6);
    color: var(--tb-primary-500, #3f51b5);
}

.dcr__percent {
    flex: 0 0 auto;
    margin-left: auto;
    min-width: 3.6em;
    text-align: right;
    font-variant-numeric: tabular-nums;
    font-weight: 500;
}

.dcr_compact .dcr__row {
    gap: 6px;
}

.dcr_compact .dcr__percent {
    min-width: 0;
}

.dcr__duration {
    flex: 0 0 auto;
    min-width: 4.6em;
    text-align: right;
    font-variant-numeric: tabular-nums;
    opacity: 0.7;
}

.dcr__notice {
    flex: 0 0 auto;
    display: flex;
    flex-direction: column;
    align-items: flex-start;
    gap: 6px;
    padding: 10px 12px;
    border-radius: 6px;
    background: #fff8e1;
    color: #6d4c41;
}

.dcr__notice-url {
    font-family: monospace;
    font-size: 0.85em;
    word-break: break-all;
    opacity: 0.8;
}

.dcr__retry {
    padding: 4px 12px;
    border: 1px solid currentColor;
    border-radius: 4px;
    background: transparent;
    color: inherit;
    cursor: pointer;
    font: inherit;
}

descriptor.controllerScript:
var AUTO_COLORS = [
    '#4CAF50',
    '#F44336',
    '#FF9800',
    '#2196F3',
    '#9C27B0',
    '#00BCD4',
    '#8BC34A',
    '#FFC107',
    '#795548',
    '#607D8B',
];

var SEMANTIC_COLORS = [
    {
        color: '#4CAF50',
        words: [
            'running',
            'run',
            'on',
            'active',
            'ok',
            'normal',
            'online',
            'enabled',
            'healthy',
            'good',
            'open',
            'ready',
            'auto',
        ],
    },
    {
        color: '#F44336',
        words: [
            'fault',
            'faulty',
            'error',
            'alarm',
            'failed',
            'failure',
            'fail',
            'critical',
            'down',
            'offline',
            'broken',
            'jammed',
            'blocked',
        ],
    },
    {
        color: '#FF9800',
        words: [
            'warning',
            'warn',
            'maintenance',
            'service',
            'idle',
            'paused',
            'pause',
            'pending',
            'degraded',
            'manual',
            'setup',
            'starting',
            'stopping',
        ],
    },
    {
        color: '#B0BEC5',
        words: [
            'off',
            'stopped',
            'stop',
            'inactive',
            'disabled',
            'unknown',
            'none',
            'closed',
            'standby',
            'sleep',
        ],
    },
];

var OTHER_KEY = '__other__';
var OTHER_COLOR = '#CFD8DC';

var ECHARTS_URL = 'https://cdnjs.cloudflare.com/ajax/libs/echarts/5.5.0/echarts.min.js';
var LIB_TIMEOUT_MS = 4000;

var DIGIT_WIDTH_RATIO = 0.62;
var MIN_CENTER_PX = 8;

self.onInit = function () {
    var ctx = self.ctx;
    var scope = ctx.$scope;

    scope.segments = [];
    scope.empty = true;
    scope.center = null;
    scope.layout = 'column';
    scope.clickable = false;
    scope.chartError = null;
    scope.echartsUrl = ECHARTS_URL;
    scope.showLegend = true;
    scope.showDurations = true;
    scope.markCurrentState = true;
    scope.compact = false;
    scope.tight = false;
    scope.nowLabel = 'now';
    scope.emptyText = 'No readings in this period';
    scope.legendFont = {};
    scope.legendColor = null;
    scope.centerValueFont = {};
    scope.centerLabelFont = {};
    scope.centerLabelColor = null;
    scope.onCardClick = function () {};
    scope.retry = function ($event) {
        if ($event) {
            $event.stopPropagation();
        }
        scope.chartError = null;
        ctx.detectChanges();
        initChart();
    };

    try {
        applySettings();
    } catch (e) {
        console.error('[duty-cycle-ring] settings could not be applied:', e);
    }

    applyLayout();
    render();
    initChart();
};

function applySettings() {
    var ctx = self.ctx;
    var scope = ctx.$scope;
    var utils = scope.$injector.get(ctx.servicesMap.get('utils'));

    self.s = utils.deepClone(ctx.settings) || {};
    var s = self.s;

    scope.showLegend = s.showLegend !== false;
    scope.showDurations = s.showDurations !== false;
    scope.markCurrentState = s.markCurrentState !== false;
    scope.legendFont = fontStyle(s.legendFont, { size: 13, weight: 'normal', lineHeight: '1.5' });
    scope.legendColor = resolveColor(s.legendColor, null, 'rgba(0, 0, 0, 0.76)');
    var sizeMode = s.centerSizeMode || (s.centerAutoScale === false ? 'manual' : 'auto');
    self.centerFonts = {
        value: { cfg: s.centerValueFont, defaults: { size: 26, weight: '500', lineHeight: '1.1' } },
        label: {
            cfg: s.centerLabelFont,
            defaults: { size: 12, weight: 'normal', lineHeight: '1.3' },
        },
        auto: sizeMode !== 'manual',
    };
    updateCenterFonts();
    scope.centerLabelColor = resolveColor(s.centerLabelColor, null, 'rgba(0, 0, 0, 0.54)');
    scope.emptyText = translate('No readings in this period');

    var descriptors = ctx.actionsApi ? ctx.actionsApi.getActionDescriptors('ringClick') : [];
    scope.clickable = !!(descriptors && descriptors.length);
    scope.onCardClick = function ($event) {
        if (!scope.clickable) {
            return;
        }
        var info = ctx.actionsApi.getActiveEntityInfo();
        ctx.actionsApi.handleWidgetAction(
            $event,
            descriptors[0],
            info ? info.entityId : null,
            info ? info.entityName : null,
        );
    };
}

self.onDataUpdated = function () {
    render();
};

self.onResize = function () {
    applyLayout();
    self.ctx.detectChanges();
    resizeChart();
};

function afterResize() {
    if (updateCenterFonts()) {
        self.ctx.detectChanges();
    }
}

self.onMobileModeChanged = function () {
    self.onResize();
};

self.onEditModeChanged = function () {
    resizeChart();
};

self.onDestroy = function () {
    stopPolling();
    if (self.sizeObserver) {
        self.sizeObserver.disconnect();
        self.sizeObserver = null;
    }
    if (self.chart) {
        self.chart.dispose();
        self.chart = null;
    }
};

self.typeParameters = function () {
    return {
        maxDatasources: 1,
        maxDataKeys: 1,
        singleEntity: true,
        dataKeysOptional: false,
        datasourcesOptional: false,
        embedTitlePanel: true,
        ignoreDataUpdateOnIntervalTick: true,
        previewWidth: '320px',
        previewHeight: '220px',
    };
};

self.actionSources = function () {
    return {
        ringClick: { name: 'Ring click', multiple: false },
    };
};

function chartElement() {
    var container = self.ctx.$container;
    var found = container ? container.find('.dcr__chart') : null;
    return found && found.length ? found[0] : null;
}

function rootElement() {
    var container = self.ctx.$container;
    return container && container.length ? container[0] : null;
}

function watchSize() {
    var root = rootElement();
    if (!root || typeof ResizeObserver === 'undefined') {
        return;
    }
    if (self.sizeObserver) {
        self.sizeObserver.disconnect();
    }
    self.sizeObserver = new ResizeObserver(function () {
        if (self.sizePending) {
            return;
        }
        self.sizePending = true;
        var run = function () {
            self.sizePending = false;

            if (!self.chart) {
                if (self.tryInit) {
                    self.tryInit();
                }
                return;
            }

            var changed = applyLayout();
            self.chart.resize();
            if (updateCenterFonts() || changed) {
                self.ctx.detectChanges();
            }
        };
        if (typeof requestAnimationFrame === 'function') {
            requestAnimationFrame(run);
        } else {
            setTimeout(run, 16);
        }
    });
    self.sizeObserver.observe(root);
    var element = chartElement();
    if (element) {
        self.sizeObserver.observe(element);
    }
}

function initChart() {
    var started = Date.now();

    stopPolling();
    watchSize();

    var tryInit = function () {
        var lib = typeof window !== 'undefined' ? window.echarts : null;

        if (!lib) {
            if (Date.now() - started > LIB_TIMEOUT_MS) {
                stopPolling();
                fail(
                    translate(
                        'The ECharts library is not available. Add it on the widget Resources tab:',
                    ),
                );
            }
            return;
        }

        var element = chartElement();
        if (!element) {
            return;
        }

        if (!element.clientWidth || !element.clientHeight) {
            if (self.sizeObserver) {
                stopPolling();
            }
            return;
        }

        stopPolling();
        try {
            if (self.chart) {
                self.chart.dispose();
            }
            self.chart = lib.init(element, null, { renderer: 'canvas' });
            applyLayout();
            render();
            resizeChart();
        } catch (e) {
            console.error('[duty-cycle-ring] chart init failed:', e);
            fail(String(e && e.message ? e.message : e));
        }
    };

    self.tryInit = tryInit;
    tryInit();
    if (!self.chart && !self.ctx.$scope.chartError) {
        self.libTimer = setInterval(tryInit, 100);
    }
}

function stopPolling() {
    if (self.libTimer) {
        clearInterval(self.libTimer);
        self.libTimer = null;
    }
}

function fail(message) {
    self.ctx.$scope.chartError = message;
    self.ctx.detectChanges();
}

function resizeChart() {
    if (!self.chart) {
        return;
    }
    setTimeout(function () {
        if (self.chart) {
            self.chart.resize();
        }
        afterResize();
    }, 0);
}

function applyLayout() {
    var scope = self.ctx.$scope;
    var mode = (self.s && self.s.legendPosition) || 'auto';
    var next;

    if (mode === 'right') {
        next = 'row';
    } else if (mode === 'bottom') {
        next = 'column';
    } else {
        var proportions = cardSize();
        next = proportions.w / proportions.h > 1.35 ? 'row' : 'column';
    }

    var size = cardSize();
    var compact = size.w < 260;
    var tight = size.w < 190;
    var changed = scope.layout !== next || scope.compact !== compact || scope.tight !== tight;

    scope.layout = next;
    scope.compact = compact;
    scope.tight = tight;
    return changed;
}

function updateCenterFonts() {
    var scope = self.ctx.$scope;
    var fonts = self.centerFonts;

    if (!fonts) {
        return false;
    }

    var configuredValue = isNum(fonts.value.cfg && fonts.value.cfg.size)
        ? fonts.value.cfg.size
        : fonts.value.defaults.size;
    var configuredLabel = isNum(fonts.label.cfg && fonts.label.cfg.size)
        ? fonts.label.cfg.size
        : fonts.label.defaults.size;

    var valueSize = configuredValue;
    var labelSize = configuredLabel;
    var side = fonts.auto && scope.center ? ringSide() : 0;

    if (side) {
        var hole = holeDiameter(side);
        var text = scope.center && scope.center.value ? String(scope.center.value) : '';
        var ratio = clamp(configuredLabel / Math.max(configuredValue, 1), 0.25, 0.8);
        var caption = !!(scope.center && scope.center.label);

        var byWidth = text.length ? (hole * 0.82) / (DIGIT_WIDTH_RATIO * text.length) : hole * 0.45;
        var byHeight = (hole * 0.78) / (1.1 + (caption ? ratio * 1.3 : 0));

        valueSize = Math.max(Math.min(byWidth, byHeight), MIN_CENTER_PX);
        labelSize = Math.max(valueSize * ratio, MIN_CENTER_PX);
    }

    var next = {
        value: fontStyle(fonts.value.cfg, fonts.value.defaults),
        label: fontStyle(fonts.label.cfg, fonts.label.defaults),
    };
    next.value['font-size'] = round1(valueSize) + 'px';
    next.label['font-size'] = round1(labelSize) + 'px';

    var changed =
        JSON.stringify(next.value) !== JSON.stringify(scope.centerValueFont) ||
        JSON.stringify(next.label) !== JSON.stringify(scope.centerLabelFont);

    scope.centerValueFont = next.value;
    scope.centerLabelFont = next.label;
    return changed;
}

function ringSide() {
    var element = chartElement();
    if (!element || !element.clientWidth || !element.clientHeight) {
        return 0;
    }
    return Math.min(element.clientWidth, element.clientHeight);
}

function ringRadii(side) {
    var thickness = clamp(num(self.s && self.s.thickness, 14), 1, 40);
    var outer = (side / 2) * 0.94;
    var inner = (outer * (49 - thickness)) / 49;
    return { outer: outer, inner: inner, mid: (outer + inner) / 2, band: outer - inner };
}

function holeDiameter(side) {
    return 2 * ringRadii(side).inner;
}

function cardSize() {
    var root = rootElement();
    var w = root && root.clientWidth ? root.clientWidth : self.ctx.width || 0;
    var h = root && root.clientHeight ? root.clientHeight : self.ctx.height || 1;
    return { w: w, h: h || 1 };
}

function render() {
    var ctx = self.ctx;
    var scope = ctx.$scope;

    try {
        self.defsCache = buildStateDefs();

        var spans = buildSpans();
        var totals = totalsFromSpans(spans);

        scope.segments = buildSegments(totals);
        scope.empty = !scope.segments.length;
        scope.center = buildCenter(scope.segments, totals.duration);
        updateCenterFonts();
        ctx.detectChanges();

        if (self.chart) {
            self.chart.setOption(buildOption(scope.segments), { replaceMerge: ['series'] });
        }
    } catch (e) {
        console.error('[duty-cycle-ring] render failed:', e);
        scope.segments = [];
        scope.empty = true;
        scope.center = null;
        ctx.detectChanges();
    }
}

function buildOption(segments) {
    var s = self.s || {};

    if (!segments.length) {
        return {
            backgroundColor: 'transparent',
            animation: false,
            tooltip: { show: false },
            series: [],
        };
    }

    var single = segments.length === 1;

    var showSliceLabels = s.showSliceLabels === true;

    var outer = 94;
    var thickness = clamp(num(s.thickness, 14), 1, 40);
    var inner = Math.max(0, round1((outer * (49 - thickness)) / 49));
    var radius = [inner + '%', outer + '%'];
    var gap = clamp(num(s.gapDegrees, 2), 0, 20);

    var trackColor = resolveColor(s.trackColor, null, '#ECEFF1');

    return {
        backgroundColor: 'transparent',
        animation: true,
        animationDuration: 500,
        animationDurationUpdate: 400,
        animationEasingUpdate: 'cubicOut',
        tooltip: {
            trigger: 'item',
            confine: true,
            appendToBody: false,
            formatter: function (params) {
                var d = params.data || {};
                return params.marker + ' ' + (d.tooltip || escapeHtml(d.name));
            },
        },
        series: [
            {
                type: 'pie',
                silent: true,
                radius: radius,
                center: ['50%', '50%'],
                label: { show: false },
                labelLine: { show: false },
                animation: false,
                emphasis: { disabled: true },
                tooltip: { show: false },
                data: [{ value: 1, itemStyle: { color: trackColor } }],
            },
            {
                type: 'pie',
                radius: radius,
                center: ['50%', '50%'],
                startAngle: 90,
                clockwise: true,
                padAngle: single ? 0 : gap,
                minAngle: segments.length > 1 ? 1 : 0,
                avoidLabelOverlap: true,
                itemStyle: {
                    borderRadius: 0,
                    borderWidth: 0,
                },
                label: {
                    show: showSliceLabels,
                    position: 'inside',
                    formatter: function (params) {
                        return params.data.percentText;
                    },
                    fontWeight: '500',
                },
                labelLine: { show: false },
                emphasis: {
                    focus: 'self',
                    scale: true,
                    scaleSize: 3,
                    label: { show: showSliceLabels },
                },
                data: segments.map(function (seg) {
                    return {
                        name: seg.label,
                        value: seg.durationMs,
                        percentText: seg.percentText,
                        durationText: seg.durationText,
                        tooltip: seg.tooltip,
                        itemStyle: { color: seg.color },
                        label: showSliceLabels ? sliceLabel(seg) : { show: false },
                    };
                }),
            },
        ],
    };
}

function sliceLabel(seg) {
    var side = ringSide();
    if (!side) {
        return { show: false };
    }

    var radii = ringRadii(side);
    var size = clamp(radii.band * 0.42, 9, 18);
    var arc = seg.share * 2 * Math.PI * radii.mid;
    var needed = DIGIT_WIDTH_RATIO * size * String(seg.percentText).length * 1.25;

    if (arc < needed || radii.band < 14) {
        return { show: false };
    }

    return {
        show: true,
        color: readableInk(seg.color),
        fontSize: round1(size),
    };
}

function readableInk(color) {
    var rgb = parseRgb(color);
    if (!rgb) {
        return '#fff';
    }
    var luminance = (0.299 * rgb[0] + 0.587 * rgb[1] + 0.114 * rgb[2]) / 255;
    return luminance > 0.62 ? 'rgba(0, 0, 0, 0.76)' : '#fff';
}

function parseRgb(color) {
    if (typeof color !== 'string') {
        return null;
    }
    var value = color.trim();
    var hex = value.match(/^#([0-9a-f]{3}|[0-9a-f]{6})$/i);
    if (hex) {
        var digits = hex[1];
        if (digits.length === 3) {
            digits = digits[0] + digits[0] + digits[1] + digits[1] + digits[2] + digits[2];
        }
        return [
            parseInt(digits.slice(0, 2), 16),
            parseInt(digits.slice(2, 4), 16),
            parseInt(digits.slice(4, 6), 16),
        ];
    }
    var rgb = value.match(/^rgba?\(([^)]+)\)$/i);
    if (rgb) {
        var parts = rgb[1].split(',');
        if (parts.length >= 3) {
            return [parseFloat(parts[0]), parseFloat(parts[1]), parseFloat(parts[2])];
        }
    }
    return null;
}

function buildSpans() {
    var points = readings();
    if (!points.length) {
        return [];
    }

    var end = windowEnd(points);
    var spans = [];

    for (var i = 0; i < points.length; i++) {
        var from = points[i].ts;
        var to = i + 1 < points.length ? points[i + 1].ts : end;
        var duration = to - from;
        if (duration <= 0) {
            continue;
        }
        spans.push({
            key: stateKey(points[i].value),
            raw: points[i].value,
            duration: duration,
        });
    }

    return spans;
}

function totalsFromSpans(spans) {
    var byKey = {};
    var rawByKey = {};
    var order = [];
    var duration = 0;
    var i;

    for (i = 0; i < spans.length; i++) {
        var key = spans[i].key;
        if (!byKey[key]) {
            byKey[key] = 0;
            rawByKey[key] = spans[i].raw;
            order.push(key);
        }
        byKey[key] += spans[i].duration;
        duration += spans[i].duration;
    }

    return {
        byKey: byKey,
        rawByKey: rawByKey,
        seen: order,
        duration: duration,
        currentKey: spans.length ? spans[spans.length - 1].key : null,
    };
}

function buildSegments(totals) {
    if (!totals.duration) {
        self.autoPresentation = null;
        return [];
    }

    var auto = detectionMode() === 'auto';
    var list = defs();
    var ordered = [];
    var used = {};
    var i;

    if (auto) {
        ordered = totals.seen.slice().sort(function (a, b) {
            return totals.byKey[b] - totals.byKey[a];
        });
        ordered = groupTail(ordered, totals);
        self.autoPresentation = buildAutoPresentation(
            ordered.filter(function (key) {
                return key !== OTHER_KEY;
            }),
            totals.rawByKey,
        );
    } else {
        self.autoPresentation = null;
        for (i = 0; i < list.length; i++) {
            var key = list[i].key;
            if (totals.byKey[key] && !used[key]) {
                used[key] = true;
                ordered.push(key);
            }
        }
        for (i = 0; i < totals.seen.length; i++) {
            if (!used[totals.seen[i]]) {
                used[totals.seen[i]] = true;
                ordered.push(totals.seen[i]);
            }
        }
    }

    var segments = [];
    for (i = 0; i < ordered.length; i++) {
        var stateName = ordered[i];
        var ms = totals.byKey[stateName];
        var share = ms / totals.duration;
        var presentation = presentationFor(stateName, i);
        var label = presentation.label;

        if (stateName === OTHER_KEY && isNum(totals.otherCount)) {
            label += ' (' + totals.otherCount + ')';
        }

        var tooltip =
            escapeHtml(label) + ' \u00b7 ' + formatPercent(share) + ' \u00b7 ' + humanizeMs(ms);

        segments.push({
            key: stateName,
            label: label,
            color: presentation.color,
            share: share,
            percentText: formatPercent(share),
            durationText: humanizeMs(ms),
            durationMs: ms,
            current: stateName === totals.currentKey,
            tooltip: tooltip,
        });
    }

    return segments;
}

function groupTail(ordered, totals) {
    var cap = clamp(num(self.s && self.s.maxStates, 8), 2, 20);
    if (ordered.length <= cap) {
        totals.otherCount = null;
        return ordered;
    }

    var kept = ordered.slice(0, cap);
    var tail = ordered.slice(cap);

    if (totals.currentKey && tail.indexOf(totals.currentKey) > -1) {
        tail.splice(tail.indexOf(totals.currentKey), 1);
        tail.push(kept.pop());
        kept.push(totals.currentKey);
    }

    var otherMs = 0;
    for (var i = 0; i < tail.length; i++) {
        otherMs += totals.byKey[tail[i]];
    }
    totals.byKey[OTHER_KEY] = otherMs;
    totals.otherCount = tail.length;
    if (tail.indexOf(totals.currentKey) > -1) {
        totals.currentKey = OTHER_KEY;
    }
    kept.push(OTHER_KEY);
    return kept;
}

function buildCenter(segments, duration) {
    var s = self.s || {};
    var mode = s.centerMode || 'largest';

    if (mode === 'none' || !segments.length) {
        return null;
    }

    if (mode === 'total') {
        return {
            value: humanizeMs(duration),
            label: translate(text(s.centerTotalLabel, 'measured')),
            color: resolveColor(s.centerValueColor, null, '#1F2937'),
        };
    }

    var pick = null;
    var i;

    if (mode === 'focus') {
        var wanted = String(text(s.focusStateLabel, '')).trim().toLowerCase();
        for (i = 0; i < segments.length; i++) {
            if (String(segments[i].label).trim().toLowerCase() === wanted) {
                pick = segments[i];
                break;
            }
        }
        if (!pick && wanted) {
            var list = defs();
            for (i = 0; i < list.length; i++) {
                if (String(list[i].label).trim().toLowerCase() === wanted) {
                    return {
                        value: formatPercent(0),
                        label: list[i].label,
                        color:
                            s.centerValueUsesStateColor === false
                                ? resolveColor(s.centerValueColor, null, '#1F2937')
                                : list[i].color,
                    };
                }
            }
        }
    } else if (mode === 'current') {
        for (i = 0; i < segments.length; i++) {
            if (segments[i].current) {
                pick = segments[i];
                break;
            }
        }
    }

    if (!pick) {
        pick = segments.slice().sort(function (a, b) {
            return b.durationMs - a.durationMs;
        })[0];
    }

    return {
        value: pick.percentText,
        label: pick.label,
        color:
            s.centerValueUsesStateColor === false
                ? resolveColor(s.centerValueColor, null, '#1F2937')
                : pick.color,
    };
}

function parseRow(row) {
    if (typeof row.match === 'string' && row.match.trim().length) {
        return parseExpression(row.match);
    }
    if (row.matchType === 'range') {
        return { kind: 'range', min: row.from, max: row.to, minIncl: true, maxIncl: false };
    }
    if (row.value !== null && row.value !== undefined && String(row.value).trim() !== '') {
        return { kind: 'constant', value: String(row.value).trim() };
    }
    return null;
}

function parseExpression(raw) {
    var token = String(raw).trim();
    var interval = token.match(/^(-?\d+(?:\.\d+)?)\s*\.\.\s*(-?\d+(?:\.\d+)?)$/);
    if (interval) {
        return {
            kind: 'range',
            min: parseFloat(interval[1]),
            max: parseFloat(interval[2]),
            minIncl: true,
            maxIncl: false,
        };
    }
    var open = token.match(/^(>=|<=|>|<)\s*(-?\d+(?:\.\d+)?)$/);
    if (open) {
        var bound = parseFloat(open[2]);
        switch (open[1]) {
            case '>=':
                return { kind: 'range', min: bound, max: null, minIncl: true, maxIncl: false };
            case '>':
                return { kind: 'range', min: bound, max: null, minIncl: false, maxIncl: false };
            case '<=':
                return { kind: 'range', min: null, max: bound, minIncl: false, maxIncl: true };
            default:
                return { kind: 'range', min: null, max: bound, minIncl: false, maxIncl: false };
        }
    }
    return { kind: 'constant', value: token };
}

function detectionMode() {
    var s = self.s || {};
    if (s.stateDetection === 'auto' || s.stateDetection === 'manual') {
        return s.stateDetection;
    }

    return Array.isArray(s.states) && s.states.length ? 'manual' : 'auto';
}

function buildStateDefs() {
    if (detectionMode() === 'auto') {
        return [];
    }
    var rows = self.s && Array.isArray(self.s.states) ? self.s.states : [];
    var out = [];
    for (var i = 0; i < rows.length; i++) {
        var row = rows[i] || {};
        var rule = parseRow(row);
        out.push({
            key: 'cfg:' + i,
            rule: rule,
            label: translate(text(row.label, ruleLabel(row, rule))),
            color: row.color || AUTO_COLORS[i % AUTO_COLORS.length],
        });
    }
    return out;
}

function defs() {
    if (!self.defsCache) {
        self.defsCache = buildStateDefs();
    }
    return self.defsCache;
}

function ruleLabel(row, rule) {
    if (typeof row.match === 'string' && row.match.trim().length) {
        return row.match.trim();
    }
    if (!rule) {
        return '';
    }
    if (rule.kind === 'range') {
        var from = isNum(rule.min) ? rule.min : '\u2212\u221E';
        var to = isNum(rule.max) ? rule.max : '\u221E';
        return from + '\u2026' + to;
    }
    return String(rule.value);
}

function stateKey(raw) {
    if (detectionMode() === 'auto') {
        return 'raw:' + String(raw).trim().toLowerCase();
    }
    var list = defs();
    var asNumber = Number(raw);
    var numeric = raw !== '' && raw !== null && raw !== undefined && isFinite(asNumber);
    var normalized = String(raw).trim().toLowerCase();

    for (var i = 0; i < list.length; i++) {
        if (matchesRule(list[i].rule, asNumber, numeric, normalized)) {
            return list[i].key;
        }
    }
    return 'raw:' + normalized;
}

function matchesRule(rule, asNumber, numeric, normalized) {
    if (!rule) {
        return false;
    }

    if (rule.kind === 'range') {
        if (!numeric) {
            return false;
        }
        if (isNum(rule.min) && (rule.minIncl ? asNumber < rule.min : asNumber <= rule.min)) {
            return false;
        }
        if (isNum(rule.max) && (rule.maxIncl ? asNumber > rule.max : asNumber >= rule.max)) {
            return false;
        }
        return true;
    }

    var target = String(rule.value).trim();
    var targetNorm = target.toLowerCase();
    var targetNumber = Number(target);

    if (numeric && isFinite(targetNumber) && target !== '' && asNumber === targetNumber) {
        return true;
    }
    if (targetNorm === normalized) {
        return true;
    }

    return !!booleanForm(targetNorm) && booleanForm(targetNorm) === booleanForm(normalized);
}

function booleanForm(token) {
    if (token === 'true' || token === '1') {
        return 'true';
    }
    if (token === 'false' || token === '0') {
        return 'false';
    }
    return null;
}

function looksBoolean(values) {
    if (!values.length || values.length > 2) {
        return false;
    }
    for (var i = 0; i < values.length; i++) {
        if (!booleanForm(String(values[i]).trim().toLowerCase())) {
            return false;
        }
    }
    return true;
}

function semanticColor(raw, booleanish) {
    var text = String(raw)
        .trim()
        .toLowerCase()
        .replace(/[_\-]+/g, ' ');
    var bool = booleanForm(text);

    if (bool && (booleanish || text === 'true' || text === 'false')) {
        return bool === 'true' ? SEMANTIC_COLORS[0].color : SEMANTIC_COLORS[3].color;
    }
    var words = text.split(' ');
    for (var i = 0; i < SEMANTIC_COLORS.length; i++) {
        var group = SEMANTIC_COLORS[i];
        for (var w = 0; w < group.words.length; w++) {
            if (words.indexOf(group.words[w]) > -1) {
                return group.color;
            }
        }
    }
    return null;
}

function paletteFor(raw) {
    var text = String(raw);
    var hash = 0;
    for (var i = 0; i < text.length; i++) {
        hash = (hash * 31 + text.charCodeAt(i)) % 100000007;
    }
    return hash % AUTO_COLORS.length;
}

function buildAutoPresentation(keys, rawByKey) {
    var values = keys.map(function (key) {
        return rawByKey && rawByKey[key] !== undefined ? rawByKey[key] : key.slice(4);
    });
    var booleanish = looksBoolean(values);
    var used = {};
    var map = {};
    var i;

    for (i = 0; i < keys.length; i++) {
        var raw = values[i];
        var color = semanticColor(raw, booleanish);
        if (color && used[color]) {
            color = null;
        }
        if (!color) {
            var index = paletteFor(raw);
            for (var step = 0; step < AUTO_COLORS.length; step++) {
                var candidate = AUTO_COLORS[(index + step) % AUTO_COLORS.length];
                if (!used[candidate]) {
                    color = candidate;
                    break;
                }
            }
            color = color || AUTO_COLORS[index];
        }
        used[color] = true;

        map[keys[i]] = { label: String(raw), color: color };
    }
    return map;
}

function presentationFor(key, index) {
    var list = defs();

    if (key === OTHER_KEY) {
        return { label: translate('Other'), color: OTHER_COLOR };
    }

    if (self.autoPresentation && self.autoPresentation[key]) {
        return self.autoPresentation[key];
    }

    if (key.indexOf('cfg:') === 0) {
        var def = list[parseInt(key.slice(4), 10)];
        if (def) {
            return { label: def.label, color: def.color };
        }
    }

    var raw = key.slice(4);
    return {
        label: raw,
        color: AUTO_COLORS[(list.length + Math.max(index, 0)) % AUTO_COLORS.length],
    };
}

function readings() {
    var data = self.ctx.data;
    if (!data || !data.length || !data[0] || !data[0].data) {
        return [];
    }
    var out = [];
    var raw = data[0].data;
    for (var i = 0; i < raw.length; i++) {
        var value = raw[i][1];
        if (value === null || value === undefined || value === '') {
            continue;
        }
        out.push({ ts: Number(raw[i][0]), value: value });
    }
    out.sort(function (a, b) {
        return a.ts - b.ts;
    });
    return out;
}

function windowEnd(points) {
    var last = points[points.length - 1].ts;
    var window = self.ctx.timeWindow;
    var to = window && isNum(window.maxTime) ? window.maxTime : last;
    return to < last ? last : to;
}

function formatPercent(share) {
    var decimals = clamp(num(self.s && self.s.percentDecimals, 1), 0, 3);
    var percent = share * 100;

    if (percent > 0 && percent < Math.pow(10, -decimals)) {
        return '<' + Math.pow(10, -decimals).toFixed(decimals) + '%';
    }
    return percent.toFixed(decimals) + '%';
}

function humanizeMs(ms) {
    var units = [
        { ms: 86400000, suffix: 'd' },
        { ms: 3600000, suffix: 'h' },
        { ms: 60000, suffix: 'm' },
        { ms: 1000, suffix: 's' },
    ];
    var left = Math.round(ms / 1000) * 1000;
    var parts = [];

    for (var i = 0; i < units.length && parts.length < 2; i++) {
        var count = Math.floor(left / units[i].ms);
        if (count > 0 || parts.length) {
            parts.push({ count: count, suffix: units[i].suffix });
            left -= count * units[i].ms;
        }
    }
    while (parts.length > 1 && parts[parts.length - 1].count === 0) {
        parts.pop();
    }
    if (!parts.length) {
        return '0 ' + translate('s');
    }
    var out = [];
    for (var j = 0; j < parts.length; j++) {
        out.push(parts[j].count + ' ' + translate(parts[j].suffix));
    }
    return out.join(' ');
}

function escapeHtml(value) {
    return String(value).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
}

function resolveColor(config, value, fallback) {
    if (!config) {
        return fallback;
    }
    if (typeof config === 'string') {
        return config;
    }
    var type = config.type || 'constant';

    if (type === 'range') {
        var ranges = config.rangeList;
        if (ranges && !Array.isArray(ranges)) {
            ranges = ranges.range;
        }
        if (Array.isArray(ranges) && isNum(value)) {
            for (var i = 0; i < ranges.length; i++) {
                var r = ranges[i] || {};
                var aboveFrom = !isNum(r.from) || value >= r.from;
                var belowTo = !isNum(r.to) || value < r.to;
                if (aboveFrom && belowTo && r.color) {
                    return r.color;
                }
            }
        }
        return config.color || fallback;
    }

    if (type === 'function' && config.colorFunction) {
        try {
            if (!config.__fn) {
                config.__fn = new Function('value', 'ctx', config.colorFunction);
            }
            var color = config.__fn(value, self.ctx);
            if (color) {
                return color;
            }
        } catch (e) {
            console.warn('[duty-cycle-ring] color function failed:', e);
        }
        return config.color || fallback;
    }

    return config.color || fallback;
}

function fontStyle(font, defaults) {
    var f = font || {};
    var d = defaults || {};
    var style = {};
    var size = isNum(f.size) ? f.size : d.size;
    if (isNum(size)) {
        style['font-size'] = size + (f.sizeUnit || d.sizeUnit || 'px');
    }
    var family = f.family || d.family;
    if (family) {
        style['font-family'] = family;
    }
    var weight = f.weight || d.weight;
    if (weight) {
        style['font-weight'] = weight;
    }
    var fontStyleValue = f.style || d.style;
    if (fontStyleValue) {
        style['font-style'] = fontStyleValue;
    }
    var lineHeight = f.lineHeight || d.lineHeight;
    if (lineHeight) {
        style['line-height'] = lineHeight;
    }
    return style;
}

function fontSize(font, fallback) {
    return font && isNum(font.size) ? font.size : fallback;
}

function translate(value) {
    try {
        if (!self.translateService) {
            self.translateService = self.ctx.$scope.$injector.get(
                self.ctx.servicesMap.get('translate'),
            );
        }
        return self.translateService.instant(value) || value;
    } catch (e) {
        return value;
    }
}

function text(value, fallback) {
    return typeof value === 'string' && value.length ? value : fallback;
}

function isNum(value) {
    return typeof value === 'number' && isFinite(value);
}

function num(value, fallback) {
    return isNum(value) ? value : fallback;
}

function clamp(value, min, max) {
    return Math.min(Math.max(value, min), max);
}

function round1(value) {
    return Math.round(value * 10) / 10;
}
